drop index if exists public.source_categories_path_unique;

create unique index if not exists source_categories_null_external_path_unique
  on public.source_categories (
    source_id,
    coalesce(brand_id, '00000000-0000-0000-0000-000000000000'::uuid),
    coalesce(audience, ''),
    original_path
  )
  where external_category_id is null;

