catalog_full_seed","catalog_snapshot_date":"2026-07-26","catalog_scope":"musinsa_product_category_apparel_sports_kids","external_category_namespace":"musinsa_product_category","evidence_url":"https://www.musinsa.com/categories/item/106?d_cat_cd=106&page_kind=category","is_leaf":false,"mapping_basis":null,"fitmatch_taxonomy_version":null}},{"source_code":"musinsa","audience":null,"external_category_id":"106013002","parent_external_category_id":"106013","name":"크로스 백","original_path":"키즈 > 가방/지갑 > 크로스 백","depth":2,"app_category":"accessories","app_detail_category":"bag","metadata":{"managed_by":"fitmatch_source_catalog_full_seed","catalog_snapshot_date":"2026-07-26","catalog_scope":"musinsa_product_category_apparel_sports_kids","external_category_namespace":"musinsa_product_category","evidence_url":"https://www.musinsa.com/categories/item/106?d_cat_cd=106&page_kind=category","is_leaf":true,"mapping_basis":"source_path_rule","fitmatch_taxonomy_version":"2026.07.1"}},{"source_code":"musinsa","audience":null,"external_category_id":"106013004","parent_external_category_id":"106013","name":"지갑","original_path":"키즈 > 가방/지갑 > 지갑","depth":2,"app_category":"accessories","app_detail_category":"bag","metadata":{"managed_by":"fitmatch_source_catalog_full_seed","catalog_snapshot_date":"2026-07-26","catalog_scope":"musinsa_product_category_apparel_sports_kids","external_category_namespace":"musinsa_product_category","evidence_url":"https://www.musinsa.com/categories/item/106?d_cat_cd=106&page_kind=category","is_leaf":true,"mapping_basis":"source_path_rule","fitmatch_taxonomy_version":"2026.07.1"}},{"source_code":"musinsa","audience":null,"external_category_id":"106013003","parent_external_category_id":"106013","name":"기타 가방","original_path":"키즈 > 가방/지갑 > 기타 가방","depth":2,"app_category":"accessories","app_detail_category":"bag","metadata":{"managed_by":"fitmatch_source_catalog_full_seed","catalog_snapshot_date":"2026-07-26","catalog_scope":"musinsa_product_category_apparel_sports_kids","external_category_namespace":"musinsa_product_category","evidence_url":"https://www.musinsa.com/categories/item/106?d_cat_cd=106&page_kind=category","is_leaf":true,"mapping_basis":"source_path_rule","fitmatch_taxonomy_version":"2026.07.1"}},{"source_code":"musinsa","audience":null,"external_category_id":"106013001","parent_external_category_id":"106013","name":"백팩","original_path":"키즈 > 가방/지갑 > 백팩","depth":2,"app_category":"accessories","app_detail_category":"bag","metadata":{"managed_by":"fitmatch_source_catalog_full_seed","catalog_snapshot_date":"2026-07-26","catalog_scope":"musinsa_product_category_apparel_sports_kids","external_category_namespace":"musinsa_product_category","evidence_url":"https://www.musinsa.com/categories/item/106?d_cat_cd=106&page_kind=category","is_leaf":true,"mapping_basis":"source_path_rule","fitmatch_taxonomy_version":"2026.07.1"}}]$fitmatch_source_categories$::jsonb) as seed (
  source_code text,
  audience text,
  external_category_id text,
  parent_external_category_id text,
  name text,
  original_path text,
  depth smallint,
  app_category text,
  app_detail_category text,
  metadata jsonb
);

do $$
declare
  seed record;
  source_uuid uuid;
  category_uuid uuid;
  parent_category_uuid uuid;
begin
  if not exists (
    select 1 from public.sources where code = 'musinsa'
  ) then
    raise exception
      'Required sources are missing. Run fitmatch_supabase_seed_sources.sql first.';
  end if;

  for seed in
    select *
    from _fitmatch_source_category_seed
    order by source_code, coalesce(audience, ''), depth, external_category_id
  loop
    select id
      into source_uuid
    from public.sources
    where code = seed.source_code;

    parent_category_uuid := null;
    if seed.parent_external_category_id is not null then
      select id
        into parent_category_uuid
      from public.source_categories
      where source_id = source_uuid
        and brand_id is null
        and coalesce(audience, '') = coalesce(seed.audience, '')
        and external_category_id = seed.parent_external_category_id;

      if parent_category_uuid is null then
        raise exception
          'Missing parent source category: source=%, audience=%, parent_external_id=%',
          seed.source_code,
          seed.audience,
          seed.parent_external_category_id;
      end if;
    end if;

    category_uuid := null;
    select id
      into category_uuid
    from public.source_categories
    where source_id = source_uuid
      and brand_id is null
      and coalesce(audience, '') = coalesce(seed.audience, '')
      and external_category_id = seed.external_category_id
    order by created_at
    limit 1;

    -- Upgrade an earlier sample row that had no verified source-owned ID.
    if category_uuid is null then
      select id
        into category_uuid
      from public.source_categories
      where source_id = source_uuid
        and brand_id is null
        and coalesce(audience, '') = coalesce(seed.audience, '')
        and external_category_id is null
        and original_path = seed.original_path
      order by created_at
      limit 1;
    end if;

    if category_uuid is null then
      insert into public.source_categories (
        source_id,
        brand_id,
        parent_id,
        external_category_id,
        name,
        original_path,
        audience,
        depth,
        app_category,
        app_detail_category,
        metadata,
        is_active
      )
      values (
        source_uuid,
        null,
        parent_category_uuid,
        seed.external_category_id,
        seed.name,
        seed.original_path,
        seed.audience,
        seed.depth,
        seed.app_category,
        seed.app_detail_category,
        seed.metadata,
        true
      );
    else
      update public.source_categories
      set
        parent_id = parent_category_uuid,
        external_category_id = seed.external_category_id,
        name = seed.name,
        original_path = seed.original_path,
        audience = seed.audience,
        depth = seed.depth,
        app_category = seed.app_category,
        app_detail_category = seed.app_detail_category,
        metadata = public.source_categories.metadata || seed.metadata,
        is_active = true,
        updated_at = now()
      where id = category_uuid;
    end if;
  end loop;

  -- A managed source-owned ID that disappeared from the new verified snapshot
  -- is retained for history but no longer treated as active reference data.
  update public.source_categories sc
  set
    is_active = false,
    updated_at = now(),
    metadata = sc.metadata || jsonb_build_object(
      'inactive_since_snapshot_date', '2026-07-26'
    )
  where sc.metadata ->> 'managed_by' = 'fitmatch_source_catalog_full_seed'
    and exists (
      select 1
      from public.sources s
      where s.id = sc.source_id
        and s.code = 'musinsa'
    )
    and not exists (
      select 1
      from _fitmatch_source_category_seed seed
      join public.sources s on s.code = seed.source_code
      where s.id = sc.source_id
        and coalesce(seed.audience, '') = coalesce(sc.audience, '')
        and seed.external_category_id = sc.external_category_id
    );

  if (
    select count(*)
    from public.source_categories sc
    join public.sources s on s.id = sc.source_id
    join _fitmatch_source_category_seed seed
      on seed.source_code = s.code
     and coalesce(seed.audience, '') = coalesce(sc.audience, '')
     and seed.external_category_id = sc.external_category_id
    where sc.brand_id is null
      and sc.is_active
      and sc.metadata ->> 'managed_by' = 'fitmatch_source_catalog_full_seed'
  ) <> 314 then
    raise exception
      'Musinsa source-category seed validation failed: expected 314 active managed rows.';
  end if;

  if exists (
    select 1
    from public.source_categories sc
    join public.sources s on s.id = sc.source_id
    join _fitmatch_source_category_seed seed
      on seed.source_code = s.code
     and coalesce(seed.audience, '') = coalesce(sc.audience, '')
     and seed.external_category_id = sc.external_category_id
    where (seed.metadata ->> 'is_leaf')::boolean
      and (sc.app_category is null or sc.app_detail_category is null)
  ) then
    raise exception
      'Musinsa source-category seed validation failed: a leaf mapping is missing.';
  end if;
end
$$;

commit;

-- Verification result. Expected managed_rows:
-- musinsa = 314.
select
  s.code as source_code,
  count(*) filter (
    where sc.metadata ->> 'managed_by' = 'fitmatch_source_catalog_full_seed'
  ) as managed_rows,
  count(*) filter (
    where sc.metadata ->> 'managed_by' = 'fitmatch_source_catalog_full_seed'
      and sc.is_active
  ) as active_managed_rows,
  count(*) filter (
    where sc.metadata ->> 'managed_by' = 'fitmatch_source_catalog_full_seed'
      and (sc.metadata ->> 'is_leaf')::boolean
  ) as managed_leaf_rows
from public.sources s
left join public.source_categories sc on sc.source_id = s.id
where s.code = 'musinsa'
group by s.code
order by s.code;

-- Must return zero rows: duplicate source-owned IDs.
select
  s.code as source_code,
  sc.audience,
  sc.external_category_id,
  count(*) as duplicate_count
from public.source_categories sc
join public.sources s on s.id = sc.source_id
where s.code = 'musinsa'
  and sc.external_category_id is not null
group by s.code, sc.audience, sc.external_category_id
having count(*) > 1;

-- Must return zero rows: child rows whose parent belongs to another source or
-- audience.
select
  child.id,
  child.original_path,
  child.audience,
  parent.original_path as parent_path,
  parent.audience as parent_audience
from public.source_categories child
join public.source_categories parent on parent.id = child.parent_id
where child.source_id <> parent.source_id
   or coalesce(child.audience, '') <> coalesce(parent.audience, '');

-- Must return zero rows: managed leaf rows without a FitMatch mapping.
select
  s.code as source_code,
  sc.audience,
  sc.external_category_id,
  sc.original_path
from public.source_categories sc
join public.sources s on s.id = sc.source_id
where s.code = 'musinsa'
  and sc.metadata ->> 'managed_by' = 'fitmatch_source_catalog_full_seed'
  and sc.is_active
  and (sc.metadata ->> 'is_leaf')::boolean
  and (sc.app_category is null or sc.app_detail_category is null);
